mapper.select:
SELECT ifnull(SUM(a.money), 0.0) total_recharge FROM ( SELECT p.member_id, p.money FROM member_recharge_online p WHERE p.status = 1
and DATE_FORMAT(p.pay_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT m.member_id, m.recharge_money money FROM member_recharge_bank m WHERE m.status = 3
and DATE_FORMAT(m.create_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT u.member_id, u.recharge_money money FROM member_recharge_usdt u WHERE u.status = 3
and DATE_FORMAT(u.create_time, '%Y-%m-%d') = #{req.inclusive_date}
) as a inner join member_info as mi on mi.id = a.member_id
where mi.inviter_code in (SELECT inviter_code from member_info where inviter_code = #{req.channelCode})
group by mi.inviter_code

select ifnull(sum(account_now), 0.0) from member_info


        and DATE_FORMAT(register_time, '%Y-%m-%d') = #{req.inclusive_date}


        and inviter_code = #{req.channelCode}

select count(id) total_registration from member_info


        and DATE_FORMAT(register_time, '%Y-%m-%d') = #{req.inclusive_date}


        and inviter_code = #{req.channelCode}

SELECT ifnull(count( a.member_id), 0) FROM ( SELECT p.member_id member_id, MIN(date(p.pay_time)) date FROM member_recharge_online p WHERE p.status = 1 group by p.member_id
having DATE_FORMAT(date, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT m.member_id member_id, MIN(date(m.create_time)) date FROM member_recharge_bank m WHERE m.status = 3 group by m.member_id
having DATE_FORMAT(date, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT u.member_id member_id, MIN(date(u.create_time)) date FROM member_recharge_usdt u WHERE u.status = 3 group by u.member_id
having DATE_FORMAT(date, '%Y-%m-%d') = #{req.inclusive_date}
) as a inner join member_info as mi on mi.id = a.member_id
where mi.inviter_code in (SELECT inviter_code from member_info where inviter_code = #{req.channelCode})

SELECT ifnull(count( distinct a.member_id), 0) total_recharge FROM ( SELECT p.member_id member_id, p.money FROM member_recharge_online p WHERE p.status = 1
and DATE_FORMAT(p.pay_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL
SELECT m.member_id member_id, m.recharge_money money FROM member_recharge_bank m WHERE m.status = 3
and DATE_FORMAT(m.create_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL
SELECT u.member_id member_id, u.recharge_money money FROM member_recharge_usdt u WHERE u.status = 3
and DATE_FORMAT(u.create_time, '%Y-%m-%d') = #{req.inclusive_date}
) as a inner join member_info as mi on mi.id = a.member_id
where mi.inviter_code in (SELECT inviter_code from member_info where inviter_code = #{req.channelCode})
